changeSet.sql:
ALTER TABLE ai_llm_call_recommendations ADD COLUMN IF NOT EXISTS previous_recommendation_id INTEGER REFERENCES ai_llm_call_recommendations(id) ON DELETE SET NULL, ADD COLUMN IF NOT EXISTS model_set_by_owner BOOLEAN NOT NULL DEFAULT FALSE, ADD COLUMN IF NOT EXISTS review_carried_over BOOLEAN NOT NULL DEFAULT FALSE;
ALTER TABLE ai_workflow_analyses DROP CONSTRAINT IF EXISTS ai_workflow_analyses_status_check; ALTER TABLE ai_workflow_analyses ADD CONSTRAINT ai_workflow_analyses_status_check CHECK (status IN ('queued', 'running', 'succeeded', 'failed', 'skipped'));
-- Older duplicates would block the index; keep the newest in flight. UPDATE ai_workflow_analyses a SET status = 'failed', error = COALESCE(a.error, 'superseded by a newer queued analysis'), finished_at = COALESCE(a.finished_at, CURRENT_TIMESTAMP) WHERE a.status IN ('queued', 'running') AND EXISTS ( SELECT 1 FROM ai_workflow_analyses n WHERE n.team_repository_id = a.team_repository_id AND n.status IN ('queued', 'running') AND n.id > a.id ); CREATE UNIQUE INDEX IF NOT EXISTS uq_ai_workflow_analyses_in_flight ON ai_workflow_analyses (team_repository_id) WHERE status IN ('queued', 'running');

rollback.sql:
DROP INDEX IF EXISTS uq_ai_workflow_analyses_in_flight;
DELETE FROM ai_workflow_analyses WHERE status = 'skipped';
ALTER TABLE ai_workflow_analyses
    DROP CONSTRAINT IF EXISTS ai_workflow_analyses_status_check;
ALTER TABLE ai_workflow_analyses
    ADD CONSTRAINT ai_workflow_analyses_status_check
    CHECK (status IN ('queued', 'running', 'succeeded', 'failed'));
ALTER TABLE ai_llm_call_recommendations
    DROP COLUMN IF EXISTS review_carried_over,
    DROP COLUMN IF EXISTS model_set_by_owner,
    DROP COLUMN IF EXISTS previous_recommendation_id;
